package com.accountaudit;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Launches a full RuneLite client with the RuneAudit plugin loaded — the standard
 * way plugin developers test against their own account before Plugin Hub publication.
 *
 *   gradlew.bat runClient      (or run this main() from an IDE)
 *
 * You log in through the normal RuneLite/Jagex login flow; the plugin never sees
 * credentials in either case.
 */
public class AccountAuditPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(AccountAuditPlugin.class);
		RuneLite.main(args);
	}
}

package com.accountaudit;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(AccountAuditConfig.GROUP)
public interface AccountAuditConfig extends Config
{
	String GROUP = "accountaudit";
	String LINK_CODE_KEY = "linkCode";
	String PLUGIN_TOKEN_KEY = "pluginToken";

	@ConfigSection(
		name = "Linking",
		description = "Connect this character to your RuneAudit profile",
		position = 0
	)
	String linkingSection = "linking";

	@ConfigItem(
		keyName = LINK_CODE_KEY,
		name = "Link code",
		description = "Paste the code from the RuneAudit website (My accounts page) while logged into the character you want to link. It is consumed on use.",
		position = 1,
		section = linkingSection
	)
	default String linkCode()
	{
		return "";
	}

	@ConfigItem(
		keyName = PLUGIN_TOKEN_KEY,
		name = "Plugin token",
		description = "Legacy slot — link tokens are now stored per character automatically. Unlink on the website to revoke a link.",
		position = 2,
		secret = true,
		hidden = true,
		section = linkingSection
	)
	default String pluginToken()
	{
		return "";
	}

	@ConfigSection(
		name = "What is synced",
		description = "Consent toggles — nothing is sent unless a category is enabled",
		position = 1
	)
	String consentSection = "consent";

	@ConfigItem(
		keyName = "syncProgress",
		name = "Sync progress data",
		description = "Sends quest completion, quest points, skill levels, and worn equipment to your private RuneAudit profile. No chat, no location.",
		position = 3,
		section = consentSection
	)
	default boolean syncProgress()
	{
		return true;
	}

	@ConfigItem(
		keyName = "bankSync",
		name = "Auto-sync bank summary (opt-in)",
		description = "OFF by default. When enabled, each time you open your bank the plugin sends a SUMMARY: total GE value, stack count, and which items from the public tracked-item list you have. The item list itself never leaves your client. Stored encrypted, visible only to you. The Sync bank button in the panel does the same on demand.",
		position = 4,
		section = consentSection
	)
	default boolean bankSync()
	{
		return false;
	}

	@ConfigItem(
		keyName = "pvpTracking",
		name = "Track PvP record",
		description = "Counts your player kills (from loot you receive), deaths to players, Wilderness loot keys picked up, and the GE value of PvP loot — from the moment the plugin is installed (an approximation), plus the lifetime loot-key totals Skully in the Ferox Enclave tells you when you ask him. Sent with progress data.",
		position = 5,
		section = consentSection
	)
	default boolean pvpTracking()
	{
		return true;
	}

	@ConfigSection(
		name = "Advanced",
		description = "Server settings",
		position = 2,
		closedByDefault = true
	)
	String advancedSection = "advanced";

	@ConfigItem(
		keyName = "apiBase",
		name = "API base URL",
		description = "Where to sync to (HTTPS only; http://localhost is allowed for development). Leave default unless you run your own instance.",
		position = 4,
		section = advancedSection
	)
	default String apiBase()
	{
		return "https://www.runeaudit.com";
	}
}

