/**
 * RuneAudit — syncs quest completion, quest points, and skill levels to the
 * player's own RuneAudit profile.
 *
 * Security & consent model (mirrors docs/plugin-spec.md in the main repo):
 * - Never touches credentials. Linking uses a short-lived code the player generates
 *   while signed into the website, pasted here — proof of control of both sides.
 * - Sends only what the consent toggles cover: quest states, quest points, levels,
 *   worn gear, diaries, personal bests, an approximate PvP record — and, separately
 *   opted in, a bank SUMMARY
 *   (total value + which published items-of-interest are present), never the bank.
 * - The account is identified by a SHA-256 of RuneLite's account hash — the raw
 *   value never leaves the client.
 */
@Slf4j
@PluginDescriptor(
	name = "RuneAudit",
	description = "Sync your progress to RuneAudit and see what's worth doing next",
	tags = {"quests", "progress", "plans", "sync"}
)
public class AccountAuditPlugin extends Plugin
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private AccountAuditConfig config;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	/** Hash of the last payload we sent, to skip no-change syncs. */
	private String lastSentDigest = null;
	private boolean syncQueued = false;
	/** Loot keys in the inventory at the last look; -1 = not yet observed this login. */
	private int lastLootKeyCount = -1;
	/** Last game tick a player targeted us — used to attribute an ambiguous death. */
	private int lastPlayerAggroTick = -1000;
	/** Tick at which to look for a new follower after a pet-drop message; -1 = idle. */
	private int petCheckTick = -1;
	/** Last Skully dialogue text parsed, so an open dialogue is read once. */
	private String lastSkullyText = null;
	/**
	 * Bank SUMMARY captured on the last bank-open, awaiting the next sync. Opt-in.
	 * Holds total value, stack counts, and which items-of-interest are present —
	 * never the inventory itself (see SCOPE.md).
	 */
	private JsonObject pendingBank = null;
	/** Lower-cased names from GET /api/items-of-interest — the only ownership vocabulary. */
	private volatile Set<String> interestNames = null;
	private AccountAuditPanel panel;
	private NavigationButton navButton;

	@Provides
	AccountAuditConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AccountAuditConfig.class);
	}

	// ---------- link token: stored PER RS PROFILE ----------
	//
	// A global token would let a second character on the same RuneLite install upload
	// its progress under the first character's link. Per-profile storage makes that
	// impossible; tokens issued before this change are migrated on first login.

	private String token()
	{
		String t = configManager.getRSProfileConfiguration(AccountAuditConfig.GROUP, AccountAuditConfig.PLUGIN_TOKEN_KEY);
		return t == null ? "" : t.trim();
	}

	private void setToken(String token)
	{
		configManager.setRSProfileConfiguration(AccountAuditConfig.GROUP, AccountAuditConfig.PLUGIN_TOKEN_KEY, token == null ? "" : token);
	}

	private void migrateGlobalToken()
	{
		String global = config.pluginToken().trim();
		if (!global.isEmpty() && token().isEmpty())
		{
			setToken(global);
			configManager.setConfiguration(AccountAuditConfig.GROUP, AccountAuditConfig.PLUGIN_TOKEN_KEY, "");
			log.info("RuneAudit: migrated link token to per-character storage");
		}
	}

	/** The API base, or null (with a panel message) if it is not HTTPS and not a local dev server. */
	private String apiBaseOrNull()
	{
		String base = config.apiBase().trim().replaceAll("/+$", "");
		boolean local = base.startsWith("http://localhost") || base.startsWith("http://127.0.0.1");
		if (!base.startsWith("https://") && !local)
		{
			panel.showStatus("API base URL must be https:// (or a localhost dev server). Check Advanced settings.");
			return null;
		}
		return base;
	}

	private boolean interestFetchInFlight = false;
	private long interestRetryAfterMs = 0;

	@Override
	protected void startUp()
	{
		panel = new AccountAuditPanel(
			this::fetchPlan,
			code -> clientThread.invokeLater(() -> tryClaimLinkCode(code)),
			() -> clientThread.invokeLater(() ->
			{
				if (client.getGameState() != GameState.LOGGED_IN)
				{
					panel.showStatus("Log into the game first, then press Sync now.");
					return;
				}
				panel.showStatus("Syncing…");
				syncQueued = false;
				collectAndSend(true);
			}),
			() -> clientThread.invokeLater(this::syncBankNow));
		panel.setOnRefreshRating(() -> refreshRating());
		navButton = NavigationButton.builder()
			.tooltip("RuneAudit")
			.icon(loadIcon())
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		fetchItemsOfInterest();
		fetchPlan();
		log.info("RuneAudit started");
	}

	@Override
	protected void shutDown()
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
		}
		lastSentDigest = null;
		pendingBank = null;
	}

	/** Sidebar icon: the RuneAudit scribe-check badge, shipped as a 16px resource. */
	private static BufferedImage loadIcon()
	{
		return ImageUtil.loadImageResource(AccountAuditPlugin.class, "panel_icon.png");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			// Quest states settle a few ticks after login; the scheduled sync picks it up.
			syncQueued = true;
			lastLootKeyCount = -1;
			lastPlayerAggroTick = -1000;
			migrateGlobalToken();
			fetchPlan();
		}
	}

	// ---------- Rating: deterministic, refreshed at most once a day on request ----------

	private static final long RATING_REFRESH_MS = 24L * 60 * 60 * 1000;

	private void refreshRating()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			panel.showStatus("Log into the character first.");
			return;
		}
		Long last = configManager.getRSProfileConfiguration(AccountAuditConfig.GROUP, "ratingRefreshedAt", long.class);
		long now = System.currentTimeMillis();
		if (last != null && now - last < RATING_REFRESH_MS)
		{
			long hours = Math.max(1, (RATING_REFRESH_MS - (now - last)) / 3_600_000);
			panel.showStatus("Audits refresh once a day — try again in about " + hours + "h. (It also updates after each sync and every night.)");
			return;
		}
		configManager.setRSProfileConfiguration(AccountAuditConfig.GROUP, "ratingRefreshedAt", now);
		panel.showStatus("Re-auditing…");
		fetchPlan();
	}

	// ---------- Pets: recorded when the drop message fires and a follower appears ----------

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		String text = event.getMessage();
		// "would have been followed" is the duplicate-pet message: no follower spawns, so
		// there is nothing safe to record from it.
		if (text.contains("funny feeling like you're being followed")
			|| text.contains("sneaking into your backpack"))
		{
			petCheckTick = client.getTickCount() + 3;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		readSkullyDialogue();
		if (petCheckTick < 0 || client.getTickCount() < petCheckTick)
		{
			return;
		}
		petCheckTick = -1;
		NPC follower = client.getFollower();
		if (follower != null && follower.getName() != null)
		{
			recordPet(follower.getName());
		}
	}

	private Set<String> knownPets()
	{
		String stored = configManager.getRSProfileConfiguration(AccountAuditConfig.GROUP, "pets");
		Set<String> pets = new LinkedHashSet<>();
		if (stored != null && !stored.isEmpty())
		{
			pets.addAll(Arrays.asList(stored.split("\\|")));
		}
		return pets;
	}

	private void recordPet(String name)
	{
		Set<String> pets = knownPets();
		if (pets.add(name))
		{
			configManager.setRSProfileConfiguration(AccountAuditConfig.GROUP, "pets", String.join("|", pets));
			syncQueued = true;
			messageLater("RuneAudit: pet recorded — " + name);
		}
	}

	private JsonArray collectPets()
	{
		Set<String> pets = knownPets();
		if (pets.isEmpty())
		{
			return null;
		}
		JsonArray arr = new JsonArray();
		for (String pet : pets)
		{
			arr.add(pet);
		}
		return arr;
	}

	// ---------- PvP record: approximate, counted client-side since install ----------
	//
	// The game exposes no lifetime PK counter, so this is built from RuneLite's own
	// events: PlayerLootReceived (a kill you looted), ActorDeath on yourself while a
	// player was involved, and loot keys appearing in the inventory. Counts persist per
	// RS profile in RuneLite's config and are sent under the progress consent toggle.
	// Missed kills (client closed, loot not picked up) are expected; the site says so.

	private static final int[] LOOT_KEYS = {
		ItemID.WILDY_LOOT_KEY0, ItemID.WILDY_LOOT_KEY1, ItemID.WILDY_LOOT_KEY2,
		ItemID.WILDY_LOOT_KEY3, ItemID.WILDY_LOOT_KEY4,
	};

	private static boolean isLootKey(int itemId)
	{
		for (int key : LOOT_KEYS)
		{
			if (key == itemId)
			{
				return true;
			}
		}
		return false;
	}

	private long pvpStat(String key)
	{
		Long value = configManager.getRSProfileConfiguration(AccountAuditConfig.GROUP, key, long.class);
		return value == null ? 0L : value;
	}

	private void bumpPvpStat(String key, long by)
	{
		if (pvpStat("pvpSince") == 0L)
		{
			configManager.setRSProfileConfiguration(AccountAuditConfig.GROUP, "pvpSince", System.currentTimeMillis());
		}
		configManager.setRSProfileConfiguration(AccountAuditConfig.GROUP, key, pvpStat(key) + by);
		syncQueued = true;
	}

	@Subscribe
	public void onPlayerLootReceived(PlayerLootReceived event)
	{
		if (!config.pvpTracking())
		{
			return;
		}
		long value = 0;
		for (ItemStack stack : event.getItems())
		{
			if (isLootKey(stack.getId()))
			{
				continue; // keys are counted when they land in the inventory
			}
			value += (long) itemManager.getItemPrice(stack.getId()) * stack.getQuantity();
		}
		bumpPvpStat("pvpKills", 1);
		if (value > 0)
		{
			bumpPvpStat("pvpLootGp", value);
		}
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		if (event.getSource() instanceof Player && event.getSource() != client.getLocalPlayer()
			&& event.getTarget() == client.getLocalPlayer())
		{
			lastPlayerAggroTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!config.pvpTracking() || event.getActor() != client.getLocalPlayer())
		{
			return;
		}
		Actor opponent = client.getLocalPlayer().getInteracting();
		boolean inPvpArea = client.getVarbitValue(Varbits.IN_WILDERNESS) == 1
			|| client.getWorldType().contains(WorldType.PVP);
		boolean playerInvolved = opponent instanceof Player
			|| client.getTickCount() - lastPlayerAggroTick < 25;
		if (inPvpArea && playerInvolved)
		{
			bumpPvpStat("pvpDeaths", 1);
		}
	}

	private void trackLootKeys(ItemContainer inventory)
	{
		if (inventory == null)
		{
			return;
		}
		int count = 0;
		for (Item item : inventory.getItems())
		{
			if (isLootKey(item.getId()))
			{
				count++;
			}
		}
		if (lastLootKeyCount >= 0 && count > lastLootKeyCount && config.pvpTracking())
		{
			bumpPvpStat("pvpLootKeys", count - lastLootKeyCount);
		}
		lastLootKeyCount = count;
	}

	/** Null until the first tracked event, so untouched characters send nothing. */
	private JsonObject collectPvp()
	{
		if (!config.pvpTracking())
		{
			return null;
		}
		long since = pvpStat("pvpSince");
		if (since == 0L)
		{
			return null;
		}
		JsonObject pvp = new JsonObject();
		pvp.addProperty("kills", pvpStat("pvpKills"));
		pvp.addProperty("deaths", pvpStat("pvpDeaths"));
		pvp.addProperty("lootKeys", pvpStat("pvpLootKeys"));
		pvp.addProperty("lootValueGp", pvpStat("pvpLootGp"));
		pvp.addProperty("since", Instant.ofEpochMilli(since).toString());
		return pvp;
	}

	// ---------- Loot-key lifetime totals, as Skully (Ferox Enclave) reports them ----------
	//
	// Asking Skully about loot keys prints the game's own lifetime figures:
	// "You've claimed N keys, containing loot worth about X gp. You've destroyed Y gp
	// worth of it." We read that dialogue line when it is on screen — the same text the
	// player is looking at — and keep the latest figures per character. Nothing is
	// clicked or sent to the game; it is only as fresh as the last time they asked.

	private static final Pattern SKULLY_CLAIMED = Pattern.compile(
		"You've claimed ([\\d,]+) keys?, containing loot worth about ([\\d,]+) ?gp");
	private static final Pattern SKULLY_DESTROYED = Pattern.compile("You've destroyed ([\\d,]+) ?gp worth");

	private static long parseGp(String digits)
	{
		try
		{
			return Long.parseLong(digits.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return -1L;
		}
	}

	private void readSkullyDialogue()
	{
		if (!config.pvpTracking())
		{
			return;
		}
		Widget name = client.getWidget(InterfaceID.ChatLeft.NAME);
		Widget body = client.getWidget(InterfaceID.ChatLeft.TEXT);
		if (name == null || body == null || name.isHidden() || body.isHidden()
			|| !"Skully".equals(Text.removeTags(name.getText())))
		{
			return;
		}
		String text = Text.removeTags(body.getText().replace("<br>", " ")).replaceAll("\\s+", " ").trim();
		if (text.equals(lastSkullyText))
		{
			return;
		}
		lastSkullyText = text;

		long claimed;
		long value;
		long destroyed;
		Matcher m = SKULLY_CLAIMED.matcher(text);
		if (m.find())
		{
			claimed = parseGp(m.group(1));
			value = parseGp(m.group(2));
			Matcher d = SKULLY_DESTROYED.matcher(text);
			if (d.find())
			{
				destroyed = parseGp(d.group(1));
			}
			else if (text.contains("destroyed everything of value"))
			{
				destroyed = value;
			}
			else if (text.contains("haven't seen you destroy anything"))
			{
				destroyed = 0L;
			}
			else
			{
				return; // a line we don't recognise — record nothing rather than guess
			}
		}
		else if (text.contains("haven't claimed a key yet"))
		{
			claimed = 0L;
			value = 0L;
			destroyed = 0L;
		}
		else
		{
			return;
		}
		if (claimed < 0 || value < 0 || destroyed < 0)
		{
			return;
		}
		configManager.setRSProfileConfiguration(AccountAuditConfig.GROUP, "skullyClaimed", claimed);
		configManager.setRSProfileConfiguration(AccountAuditConfig.GROUP, "skullyValueGp", value);
		configManager.setRSProfileConfiguration(AccountAuditConfig.GROUP, "skullyDestroyedGp", destroyed);
		configManager.setRSProfileConfiguration(AccountAuditConfig.GROUP, "skullyReadAt", System.currentTimeMillis());
		syncQueued = true;
		messageLater("RuneAudit: loot-key totals recorded from Skully — " + claimed + " keys.");
	}

	/** Null until the player has asked Skully at least once with the plugin running. */
	private JsonObject collectLootKeysLifetime()
	{
		if (!config.pvpTracking())
		{
			return null;
		}
		long readAt = pvpStat("skullyReadAt");
		if (readAt == 0L)
		{
			return null;
		}
		JsonObject keys = new JsonObject();
		keys.addProperty("claimed", pvpStat("skullyClaimed"));
		keys.addProperty("valueGp", pvpStat("skullyValueGp"));
		keys.addProperty("destroyedGp", pvpStat("skullyDestroyedGp"));
		keys.addProperty("readAt", Instant.ofEpochMilli(readAt).toString());
		return keys;
	}

	// ---------- Combat Achievements and collection log totals ----------

	/**
	 * Combat Achievement points and per-tier task counts, from the game's own varbits.
	 * Null at zero: an all-zero read can't be told apart from varbits that haven't
	 * loaded yet, and sending it would overwrite a real total with nothing.
	 */
	private JsonObject collectCombatAchievements()
	{
		int[] tiers = {
			client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_EASY),
			client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_MEDIUM),
			client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_HARD),
			client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_ELITE),
			client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_MASTER),
			client.getVarbitValue(VarbitID.CA_TOTAL_TASKS_COMPLETED_GRANDMASTER),
		};
		int fromTasks = 0;
		for (int i = 0; i < tiers.length; i++)
		{
			fromTasks += tiers[i] * (i + 1);
		}
		int points = Math.max(client.getVarbitValue(VarbitID.CA_POINTS), fromTasks);
		if (points <= 0)
		{
			return null;
		}
		JsonObject ca = new JsonObject();
		ca.addProperty("points", points);
		String[] names = {"easy", "medium", "hard", "elite", "master", "grandmaster"};
		for (int i = 0; i < names.length; i++)
		{
			ca.addProperty(names[i], tiers[i]);
		}
		return ca;
	}

	/** The in-game collection log count; only populated once the log has been opened. */
	private JsonObject collectCollectionLog()
	{
		int count = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
		int max = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
		if (count <= 0 || max <= 0 || count > max)
		{
			return null;
		}
		JsonObject clog = new JsonObject();
		clog.addProperty("count", count);
		clog.addProperty("max", max);
		return clog;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INVENTORY.getId())
		{
			trackLootKeys(event.getItemContainer());
			return;
		}
		// Automatic bank-summary capture: opt-in toggle, fires while the bank is open.
		if (!config.bankSync() || event.getContainerId() != InventoryID.BANK.getId())
		{
			return;
		}
		if (captureBank(event.getItemContainer()))
		{
			syncQueued = true;
		}
	}

	/**
	 * Reduce a bank container to the summary we are willing to transmit:
	 * total GE value (priced locally by RuneLite's ItemManager, coins/platinum at face
	 * value), stack counts, and which published items-of-interest are present. Item
	 * names and quantities never leave this method. Returns false when unavailable.
	 */
	private boolean captureBank(ItemContainer bankContainer)
	{
		if (bankContainer == null)
		{
			return false;
		}
		Set<String> interest = interestNames;
		if (interest == null)
		{
			// Without the published list we can't say what's owned — fetch and wait.
			fetchItemsOfInterest();
			return false;
		}
		long valueGp = 0;
		int itemCount = 0;
		int unpriced = 0;
		Set<String> owned = new HashSet<>();
		for (Item item : bankContainer.getItems())
		{
			if (item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			itemCount++;
			int unit = itemManager.getItemPrice(item.getId());
			if (unit > 0)
			{
				valueGp += (long) unit * item.getQuantity();
			}
			else
			{
				unpriced++;
			}
			String name = client.getItemDefinition(item.getId()).getName().toLowerCase(Locale.ROOT);
			for (String tracked : interest)
			{
				// "toxic blowpipe (empty)" owns "toxic blowpipe"; "bow of faerdhinen (c)" owns
				// "bow of faerdhinen". Only bank-name-contains-tracked-name, never the reverse,
				// so a plain "Cape" can't claim a fire cape.
				if (name.contains(stripVariant(tracked)))
				{
					owned.add(tracked);
				}
			}
		}
		JsonObject summary = new JsonObject();
		summary.addProperty("valueGp", valueGp);
		summary.addProperty("itemCount", itemCount);
		summary.addProperty("unpricedCount", unpriced);
		JsonArray ownedArr = new JsonArray();
		for (String tracked : owned)
		{
			ownedArr.add(tracked);
		}
		summary.add("owned", ownedArr);
		pendingBank = summary;
		return true;
	}

	private static String stripVariant(String trackedName)
	{
		return trackedName.replace(" (c)", "").replace(" (f)", "");
	}

	/**
	 * The published vocabulary of ownership flags. Fetched once per session; anyone can
	 * open the URL to see exactly which item names the plugin may ever report.
	 */
	private void fetchItemsOfInterest()
	{
		if (interestFetchInFlight || System.currentTimeMillis() < interestRetryAfterMs)
		{
			return;
		}
		String base = apiBaseOrNull();
		if (base == null)
		{
			return;
		}
		interestFetchInFlight = true;
		Request request = new Request.Builder()
			.url(base + "/api/items-of-interest")
			.get()
			.build();
		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				interestFetchInFlight = false;
				interestRetryAfterMs = System.currentTimeMillis() + 60_000;
				log.debug("RuneAudit: items-of-interest fetch failed", e);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				interestFetchInFlight = false;
				try (Response r = response)
				{
					if (!r.isSuccessful() || r.body() == null)
					{
						interestRetryAfterMs = System.currentTimeMillis() + 60_000;
						return;
					}
					JsonObject json = gson.fromJson(r.body().string(), JsonObject.class);
					if (!json.has("names"))
					{
						return;
					}
					Set<String> names = new HashSet<>();
					for (JsonElement el : json.getAsJsonArray("names"))
					{
						names.add(el.getAsString().toLowerCase(Locale.ROOT));
					}
					interestNames = names;
				}
			}
		});
	}

	/**
	 * The panel's Sync bank button — pressing it is explicit consent for this send.
	 * The client keeps the bank container in memory after one visit per session, so
	 * this works from anywhere once the bank has been opened.
	 */
	private void syncBankNow()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			panel.showStatus("Log into the game first, then press Sync bank.");
			return;
		}
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank == null)
		{
			panel.showStatus("Open your bank once this session, close it if you like, then press Sync bank again.");
			return;
		}
		if (!captureBank(bank))
		{
			panel.showStatus(interestNames == null
				? "Fetching the tracked-item list from the server — try again in a moment."
				: "Couldn't read the bank — open it and try again.");
			return;
		}
		panel.showStatus("Sending bank summary (value + " + pendingBank.getAsJsonArray("owned").size()
			+ " tracked items, no inventory)…");
		collectAndSend(true);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!AccountAuditConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (AccountAuditConfig.LINK_CODE_KEY.equals(event.getKey())
			&& event.getNewValue() != null && !event.getNewValue().trim().isEmpty())
		{
			final String code = event.getNewValue();
			clientThread.invokeLater(() -> tryClaimLinkCode(code));
		}
	}

	/** Runs every 30s; actually syncs on login and every ~5 minutes, or when queued. */
	@Schedule(period = 30, unit = ChronoUnit.SECONDS)
	public void scheduledSync()
	{
		if (!syncQueued)
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				syncQueued = false;
				collectAndSend();
			}
		});
	}

	@Schedule(period = 5, unit = ChronoUnit.MINUTES)
	public void periodicSync()
	{
		syncQueued = true;
	}

	// ---------- linking ----------

	private void tryClaimLinkCode(String rawCode)
	{
		final String code = rawCode == null ? "" : rawCode.trim().toUpperCase();
		if (code.isEmpty())
		{
			panel.showStatus("Paste the code from the website first, then press Link.");
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			panel.showStatus("Log into the character you want to link, then press Link again.");
			message("RuneAudit: log into the character you want to link, then try again.");
			return;
		}
		final long accountHash = client.getAccountHash();
		if (accountHash == -1)
		{
			panel.showStatus("Account identity not ready — wait a moment and press Link again.");
			return;
		}
		panel.showStatus("Linking…");
		final String displayName = Objects.requireNonNull(client.getLocalPlayer().getName());

		JsonObject body = new JsonObject();
		body.addProperty("code", code);
		body.addProperty("accountHash", sha256Hex(Long.toString(accountHash)));
		body.addProperty("displayName", displayName);

		String base = apiBaseOrNull();
		if (base == null)
		{
			return;
		}
		Request request = new Request.Builder()
			.url(base + "/api/link")
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("RuneAudit link failed", e);
				panel.showStatus("Couldn't reach the server (" + e.getMessage() + "). Check your connection and press Link again.");
				messageLater("RuneAudit: couldn't reach the server (" + e.getMessage() + ").");
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					String responseBody = r.body() != null ? r.body().string() : "";
					if (!r.isSuccessful())
					{
						log.warn("RuneAudit link rejected: {} {}", r.code(), responseBody);
						String reason = friendlyError(responseBody, r.code());
						panel.showStatus("Link failed: " + reason);
						messageLater("RuneAudit: link failed (" + reason + ")");
						return;
					}
					JsonObject json = gson.fromJson(responseBody, JsonObject.class);
					String token = json.get("pluginToken").getAsString();
					setToken(token);
					configManager.setConfiguration(AccountAuditConfig.GROUP, AccountAuditConfig.LINK_CODE_KEY, "");
					panel.setLinked(true);
					panel.showStatus("Linked as " + displayName + " ✓ — syncing…");
					messageLater("RuneAudit: " + displayName + " linked successfully. Syncing…");
					clientThread.invokeLater(() -> collectAndSend(true));
				}
			}
		});
	}

	// ---------- syncing ----------

	private void collectAndSend()
	{
		collectAndSend(false);
	}

	/** Must run on the client thread (reads quest state). force = ignore no-change skip. */
	private void collectAndSend(boolean force)
	{
		if (!config.syncProgress())
		{
			if (force)
			{
				panel.showStatus("Progress sync is disabled in the plugin settings.");
			}
			return;
		}
		final String token = token();
		if (token.isEmpty())
		{
			if (force)
			{
				panel.showStatus("Not linked yet — paste a code from the website above and press Link.");
			}
			return;
		}
		final String base = apiBaseOrNull();
		if (base == null)
		{
			return;
		}

		JsonObject quests = new JsonObject();
		for (Quest quest : Quest.values())
		{
			QuestState state = quest.getState(client);
			quests.addProperty(kebab(quest.getName()), mapState(state));
		}

		JsonObject levels = new JsonObject();
		for (Skill skill : Skill.values())
		{
			String key = skill.name().toLowerCase(Locale.ROOT);
			if (SkillKeys.KNOWN.contains(key))
			{
				levels.addProperty(key, client.getRealSkillLevel(skill));
			}
		}

		// Worn equipment only — visible to anyone in-game, so it sits in the progress
		// consent category. Bank is NOT read; that's a separate opt-in in a later phase.
		JsonArray equipment = new JsonArray();
		ItemContainer worn = client.getItemContainer(InventoryID.EQUIPMENT);
		if (worn != null)
		{
			for (Item item : worn.getItems())
			{
				if (item.getId() <= 0)
				{
					continue;
				}
				JsonObject entry = new JsonObject();
				entry.addProperty("id", item.getId());
				entry.addProperty("name", client.getItemDefinition(item.getId()).getName());
				entry.addProperty("qty", item.getQuantity());
				equipment.add(entry);
			}
		}

		JsonObject delta = new JsonObject();
		delta.add("quests", quests);
		delta.add("levels", levels);
		delta.add("equipment", equipment);
		delta.add("diaries", collectDiaries());
		delta.add("personalBests", collectPersonalBests());
		JsonObject pvp = collectPvp();
		if (pvp != null)
		{
			delta.add("pvp", pvp);
		}
		JsonArray pets = collectPets();
		if (pets != null)
		{
			delta.add("pets", pets);
		}
		JsonObject lootKeys = collectLootKeysLifetime();
		if (lootKeys != null)
		{
			delta.add("lootKeysLifetime", lootKeys);
		}
		JsonObject ca = collectCombatAchievements();
		if (ca != null)
		{
			delta.add("combatAchievements", ca);
		}
		JsonObject clog = collectCollectionLog();
		if (clog != null)
		{
			delta.add("collectionLog", clog);
		}
		// Quest points varp (101) — stable id; gameval constant is VarPlayerID.QP on new APIs.
		delta.addProperty("questPoints", client.getVarpValue(101));
		if (client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null)
		{
			delta.addProperty("displayName", client.getLocalPlayer().getName());
		}

		// Digest covers progress only; a pending bank summary always forces a send.
		String digest = sha256Hex(delta.toString());
		final JsonObject bankToSend = pendingBank;
		if (!force && digest.equals(lastSentDigest) && bankToSend == null)
		{
			return; // nothing changed since last sync
		}
		if (bankToSend != null)
		{
			delta.add("bankSummary", bankToSend);
		}

		JsonObject payload = new JsonObject();
		payload.addProperty("schemaVersion", 1);
		payload.addProperty("capturedAt", Instant.now().toString());
		payload.add("delta", delta);

		Request request = new Request.Builder()
			.url(base + "/api/ingest")
			.header("Authorization", "Bearer " + token)
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.build();

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				syncQueued = true; // keep the change queued for the next tick
				panel.showStatus("Sync failed: couldn't reach the server. Will retry automatically.");
				log.warn("RuneAudit sync failed", e);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (Response r = response)
				{
					if (r.isSuccessful())
					{
						lastSentDigest = digest;
						if (bankToSend != null && bankToSend == pendingBank)
						{
							pendingBank = null;
						}
						panel.showStatus("Synced ✓ — loading your plan…");
						fetchPlan();
						log.debug("RuneAudit: synced");
					}
					else if (r.code() == 401)
					{
						log.warn("RuneAudit: token revoked; clearing. Re-link from the website.");
						if (token.equals(token()))
						{
							setToken(""); // only the token this request used — never a newer one
						}
						panel.setLinked(false);
						panel.showStatus("This link was revoked on the website — generate a new code and re-link.");
						messageLater("RuneAudit: this link was revoked — generate a new code on the website to re-link.");
					}
					else if (r.code() == 429)
					{
						if (force)
						{
							panel.showStatus("Synced very recently — wait ~30 seconds and try again.");
						}
					}
					else if (r.code() == 503 && bankToSend != null)
					{
						// Server has no bank encryption key: drop the summary so progress isn't blocked.
						pendingBank = null;
						syncQueued = true;
						panel.showStatus("The server refused the bank summary (no encryption key configured) — progress will keep syncing without it.");
					}
					else
					{
						syncQueued = true;
						panel.showStatus("Sync failed (HTTP " + r.code() + ") — will retry automatically.");
						log.warn("RuneAudit sync rejected: {}", r.code());
					}
				}
			}
		});
	}

